from _lib import File
F=File('pre2020_gaps6','o-gv','Sixth fill of uncovered pre-2020 off-road years: Husqvarna FX 350 2017, 2016 TE/FE range, TX 125 2018, KTM 250 XC-F 2018 (knowledge push 2026-11)','Husqvarna',['FX 350'],list(range(2010,2020)))
R=F.R; K='KTM'; Q='Husqvarna'; A='article'; M='magazine'
s=F.src(M,"Ultimate Motorcycling - 2017 Husqvarna FX 350 first ride","https://ultimatemotorcycling.com/2016/06/09/2017-husqvarna-fx-350-first-ride-review-10-fast-facts/","2016")
R('identity','FX 350 2017: how it differs from the FC 350',['FX 350'],[2017],"The 2017 FX 350 is the cross-country version of the FC 350: a six-speed gearbox (one more than the FC), the WP AER 48 air fork with air on the left leg and damping on the right, a clear 2.2-gallon tank with the extra fuel carried low, an 18-inch rear wheel, handguards, a Magura clutch and a lithium-ion battery for the starter. The air fork is 3.6 lb lighter than the 4CS it replaced.",{'gearbox':'6-speed','tank_gal':2.2,'rear_wheel_in':18,'fork':'WP AER 48'},'OEM',s,make=Q)
R('setups','FX 350 2017 air fork notes',['FX 350'],[2017],"On the 2017 FX 350 the air fork is plush off-road and a little soft for motocross. To stop it bottoming, raise the air pressure, stiffen the clicker, or both. Check the pressure with the supplied gauge before every ride.",{},'TUNER',s,make=Q)
s=F.src(M,"Dirt Bike Test - 2017 Husqvarna FX350 and FX450 first impression","https://dirtbiketest.com/fresh-dirt/first-impression-2017-husqvarna-fx350-and-fx450/","2016")
R('power_feel','FX 350 against FX 450 (2017)',['FX 350','FX 450'],[2017],"Of the 2017 pair, the FX 350 feels light and free-revving, like a 250 with far more power, and keeps pulling to very high rpm. It lacks the 450's low-end, does not chug well at very low revs and stalls in tight technical sections unless the clutch is covered; extra flywheel weight was suggested for hard enduro. The FX 450 feels heavier and more stable, has more low-end torque, lugs to a crawl without stalling and finds traction better on technical ground, helped by its two maps and traction control. Neither has a spark arrestor.",{},'TUNER',s,make=Q)
R('known_issues','FX 350 and FX 450 2017 stock suspension limits',['FX 350','FX 450'],[2017],"Both the 2017 FX 350 and FX 450 are soft on jump faces, harsh on landings and bottom on large jumps as delivered; hard motocross use needs suspension work. The 450 is slightly firm on slow, technical off-road sections.",{},'TUNER',s,make=Q)
s=F.src(M,"Cycle News - 2016 Husqvarna off-road and dual sport first look","https://www.cyclenews.com/2015/06/article/first-look-2016-husqvarna-off-road-and-dual-sport/","2015")
R('identity','TE and FE range 2016 updates',['TE 250','TE 300','FE 350','FE 450','FE 501'],[2016],"For 2016 all TE and FE models got a 22 mm front axle in place of the 26 mm one, triple-clamp offset increased 2 mm to 22 mm, a revised 4CS fork setting and a new shock setting, open fork protectors, new front and rear brake discs, lighter spokes, a grippier seat cover, a map switch as standard and four bar-mount positions. The FE 350 also got a modified lubrication system (better oiling in extreme conditions and protection against overfilling), a new gearbox input-shaft bearing for smoother shifts and a new shift-lever bolt. The FE 450 and FE 501 got an updated DDS clutch with a basket 80 g lighter. No model-specific changes were listed for the TE 250 or TE 300.",{'front_axle_mm':'22 (was 26)','offset_mm':22,'map_switch':'standard'},'OEM',s,make=Q)
s=F.src(A,"1000PS - 2018 Husqvarna TX 125 specifications","https://www.1000ps.com/en-us/model/8729/husqvarna-tx-125/2018","2018")
R('identity','TX 125 2018 layout',['TX 125'],[2018],"The 2018 TX 125 is a 124.8 cc (54 x 54.5 mm) kick-start two-stroke with a six-speed gearbox, 300 mm of front and 330 mm of rear travel, a 10-litre tank, a 960 mm seat, a 21-inch front and 18-inch rear wheel, and a dry weight of 92 kg.",{'bore_stroke_mm':'54 x 54.5','starter':'kick','dry_weight_kg':92,'tank_l':10,'seat_mm':960},'OEM',s,'low',make=Q)
s=F.src(A,"Motorcycle.com - 2018 KTM 250 XC-F specifications","https://www.motorcycle.com/specs/ktm/off-road/2018/xc/250-f/detail.html","2018")
R('identity','250 XC-F 2018 specs',['250 XC-F'],[2018],"The 2018 250 XC-F is a 249.9 cc DOHC four-valve engine (78 x 52.3 mm, 14.4:1) with Keihin fuel injection and a six-speed gearbox. It uses the WP AER air fork (310 mm travel) and a linkage shock (300 mm), holds 2.3 gallons, has a 960 mm seat and a listed dry weight of 218.7 lb.",{'compression':'14.4:1','gearbox':'6-speed','fork':'WP AER','tank_gal':2.3,'dry_weight_lb':218.7,'seat_mm':960},'OEM',s,'low',make=K)
if __name__=='__main__': F.write()
